import pathlib, re
scope='/tmp/NHE20/1163/scope_1.txt'
paths=[l.strip() for l in open(scope) if l.strip()]
patterns=[
    ('phones open',re.compile(r'phones?\s+open',re.I)),
    ('our phones open',re.compile(r'our\s+phones\s+open',re.I)),
    ('joint financial',re.compile(r'joint\s+financial',re.I)),
    ('financial account',re.compile(r'financial\s+account',re.I)),
    ('introduced by a friend',re.compile(r'introduced\s+by\s+a\s+friend',re.I)),
    ('shared faculty',re.compile(r'shared\s+faculty',re.I)),
    ('17 years',re.compile(r'17\s+years',re.I)),
    ('co-owned an agency',re.compile(r'co[- ]owned\s+an\s+agency',re.I)),
    ('agency in atlanta',re.compile(r'agency\s+in\s+atlanta',re.I)),
    ('project in 2006',re.compile(r'project\s+(created\s+)?in\s+2006',re.I)),
]

hits={k:[] for k,_ in patterns}
for p in paths:
    fp=pathlib.Path(p)
    if not fp.exists():
        continue
    try:
        if fp.stat().st_size>3_000_000:
            continue
        txt=fp.read_text(errors='ignore')
    except: 
        continue
    for name,rgx in patterns:
        if rgx.search(txt):
            hits[name].append(p)

for name,_ in patterns:
    if hits[name]:
        print(name,'->',len(hits[name]))
        for p in hits[name][:10]:
            print(' ',p)
